#define SENSOR_PERIOD_MS  100U   /* sensor + UART line period */

/* 3-sample debounce (same logic the button tasks already used). */
typedef struct { int rawPrev; int stable; int state; } Debounce_t;

static int debounce_update(Debounce_t *d, int raw)
{
  if (raw == d->rawPrev) { if (d->stable < 2) d->stable++; }
  else                   { d->stable = 0; }
  d->rawPrev = raw;
  if (d->stable >= 2) d->state = raw;
  return d->state;
}

/* Empty a queue completely. *any = OR of every value received (so a short
 * tap that rose and fell between two prints is still seen), *last = newest
 * value. Returns how many items were drained. */
static int drain_queue(osMessageQueueId_t q, uint16_t *any, uint16_t *last)
{
  uint16_t v;
  int n = 0;
  *any = 0;
  while (osMessageQueueGet(q, &v, NULL, 0) == osOK) {
    *any |= v;
    *last = v;
    n++;
  }
  return n;
}
