/**
  * @brief  FreeRTOS initialization
  * @param  None
  * @retval None
  */
void MX_FREERTOS_Init(void) {
  /* USER CODE BEGIN Init */

  /* USER CODE END Init */

  /* USER CODE BEGIN RTOS_MUTEX */
  /* add mutexes, ... */
  /* USER CODE END RTOS_MUTEX */

  /* USER CODE BEGIN RTOS_SEMAPHORES */
  /* add semaphores, ... */
  /* USER CODE END RTOS_SEMAPHORES */

  /* USER CODE BEGIN RTOS_TIMERS */
  /* start timers, add new ones, ... */
  /* USER CODE END RTOS_TIMERS */

  /* Create the queue(s) */
  /* creation of sensorQueue */
  sensorQueueHandle = osMessageQueueNew (4, sizeof(SensorPacket_t), &sensorQueue_attributes);

  /* creation of resetQueue */
  resetQueueHandle = osMessageQueueNew (8, sizeof(uint16_t), &resetQueue_attributes);

  /* creation of leftQueue */
  leftQueueHandle = osMessageQueueNew (8, sizeof(uint16_t), &leftQueue_attributes);

  /* creation of rightQueue */
  rightQueueHandle = osMessageQueueNew (8, sizeof(uint16_t), &rightQueue_attributes);

  /* creation of headlightQueue */
  headlightQueueHandle = osMessageQueueNew (8, sizeof(uint16_t), &headlightQueue_attributes);

  /* USER CODE BEGIN RTOS_QUEUES */
  /* add queues, ... */
  /* USER CODE END RTOS_QUEUES */

  /* Create the thread(s) */
  /* creation of SensorTask */
  SensorTaskHandle = osThreadNew(StartDefaultTask06, NULL, &SensorTask_attributes);

  /* creation of HeadlightTask */
  HeadlightTaskHandle = osThreadNew(StartTask01, NULL, &HeadlightTask_attributes);

  /* creation of LeftSignalTask */
  LeftSignalTaskHandle = osThreadNew(StartTask02, NULL, &LeftSignalTask_attributes);

  /* creation of RightSignalTask */
  RightSignalTaskHandle = osThreadNew(StartTask03, NULL, &RightSignalTask_attributes);

  /* creation of ResetButtonTask */
  ResetButtonTaskHandle = osThreadNew(StartTask04, NULL, &ResetButtonTask_attributes);

  /* creation of UartTask */
  UartTaskHandle = osThreadNew(StartTask05, NULL, &UartTask_attributes);

  /* USER CODE BEGIN RTOS_THREADS */
  /* UartTask uses a blocking (polling) transmit, so it must be the LOWEST
   * priority task: it then runs in the gaps and never starves the sensor
   * or button tasks. Set here so CubeMX regeneration doesn't undo it. */
  osThreadSetPriority(SensorTaskHandle,     osPriorityAboveNormal);
  osThreadSetPriority(HeadlightTaskHandle,  osPriorityNormal);
  osThreadSetPriority(LeftSignalTaskHandle, osPriorityNormal);
  osThreadSetPriority(RightSignalTaskHandle,osPriorityNormal);
  osThreadSetPriority(ResetButtonTaskHandle,osPriorityNormal);
  osThreadSetPriority(UartTaskHandle,       osPriorityLow);
  /* USER CODE END RTOS_THREADS */

  /* USER CODE BEGIN RTOS_EVENTS */
  /* add events, ... */
  /* USER CODE END RTOS_EVENTS */

}

/* USER CODE BEGIN Header_StartDefaultTask06 */
/**
  * @brief  Function implementing the SensorTask thread.
  *         Reads the MPU6050 on a fixed 100 ms period (osDelayUntil),
  *         using the real elapsed time as dt, and pushes one packet into
  *         sensorQueue for UartTask to pick up.
  * @param  argument: Not used
  * @retval None
  */
/* USER CODE END Header_StartDefaultTask06 */
void StartDefaultTask06(void *argument)
{
  /* USER CODE BEGIN StartDefaultTask06 */
  uint32_t next = osKernelGetTickCount();
  uint32_t last = next;
  for(;;)
  {
    /* Real elapsed time since the previous read, so the complementary
     * filter integrates the gyro over the true dt. */
    uint32_t now = osKernelGetTickCount();
    float dt = (float)(now - last) / 1000.0f;
    last = now;
    if (dt <= 0.0f || dt > 0.5f) dt = SENSOR_PERIOD_MS / 1000.0f;  /* first pass / hiccup */

    MPU6050_Read_All(&hi2c3, &mpu, dt);
    SensorPacket_t packet = {
      .Ax = mpu.Ax, .Ay = mpu.Ay, .Az = mpu.Az,
      .Gx = mpu.Gx, .Gy = mpu.Gy, .Gz = mpu.Gz,
      .Temp = mpu.Temperature
    };
    /* Non-blocking put: drop if UartTask is behind rather than stall. */
    osMessageQueuePut(sensorQueueHandle, &packet, 0, 0);

    /* Fixed period (no drift from the work above). */
    next += SENSOR_PERIOD_MS;
    osDelayUntil(next);
  }
  /* USER CODE END StartDefaultTask06 */
}

/* USER CODE BEGIN Header_StartTask01 */
/**
* @brief Function implementing the HeadlightTask thread.
*        Polls PA6 every 20 ms, debounces, cycles the brightness mode
*        (0 off / 1 half / 2 full), drives TIM1_CH1 PWM directly, and posts
*        (mode << 1 | button level) into headlightQueue for UartTask.
* @param argument: Not used
* @retval None
*/
/* USER CODE END Header_StartTask01 */
void StartTask01(void *argument)
{
  /* USER CODE BEGIN StartTask01 */
  Debounce_t deb = {0, 0, 0};
  int headprev = 0, headtype = 0;
  for(;;)
  {
    int raw = (HAL_GPIO_ReadPin(GPIOA, GPIO_PIN_6) == GPIO_PIN_RESET) ? 1 : 0;
    int buttonhead = debounce_update(&deb, raw);
    if (buttonhead == 1 && headprev == 0) {
      headtype++;
      if (headtype == 3) headtype = 0;
      __HAL_TIM_SET_COMPARE(&htim1, TIM_CHANNEL_1, (headtype * 50));
    }
    headprev = buttonhead;
    /* bit0 = button level, bits1..2 = current brightness mode (0/1/2) */
    uint16_t value = (uint16_t)((headtype << 1) | buttonhead);
    osMessageQueuePut(headlightQueueHandle, &value, 0, 0);
    osDelay(20);
  }
  /* USER CODE END StartTask01 */
}

/* USER CODE BEGIN Header_StartTask02 */
/**
* @brief Function implementing the LeftSignalTask thread.
*        Polls PA4, debounces, pushes the debounced 0/1 state into
*        leftQueue.
* @param argument: Not used
* @retval None
*/
/* USER CODE END Header_StartTask02 */
void StartTask02(void *argument)
{
  /* USER CODE BEGIN StartTask02 */
  int rawPrev = 0, stableCount = 0, state = 0;

  for(;;)
  {
    int raw = (HAL_GPIO_ReadPin(GPIOA, GPIO_PIN_4) == GPIO_PIN_RESET) ? 1 : 0;

    if (raw == rawPrev) {
      if (stableCount < 2) stableCount++;
    } else {
      stableCount = 0;
    }
    rawPrev = raw;

    if (stableCount >= 2) {
      state = raw;
    }

    uint16_t value = (uint16_t)state;
    osMessageQueuePut(leftQueueHandle, &value, 0, 0);

    osDelay(20);
  }
  /* USER CODE END StartTask02 */
}

