/* USER CODE BEGIN Header_StartTask04 */
/**
* @brief Function implementing the ResetButtonTask thread.
*        Polls PA3, debounces, pushes the debounced 0/1 state into
*        resetQueue.
* @param argument: Not used
* @retval None
*/
/* USER CODE END Header_StartTask04 */
void StartTask04(void *argument)
{
  /* USER CODE BEGIN StartTask04 */
  int buttonRawPrev = 0, buttonStableCount = 0, button = 0;

  for(;;)
  {
    int buttonRaw = (HAL_GPIO_ReadPin(GPIOA, GPIO_PIN_3) == GPIO_PIN_RESET) ? 1 : 0;

    if (buttonRaw == buttonRawPrev) {
      if (buttonStableCount < 2) buttonStableCount++;
    } else {
      buttonStableCount = 0;
    }
    buttonRawPrev = buttonRaw;

    if (buttonStableCount >= 2) {
      button = buttonRaw;
    }

    uint16_t value = (uint16_t)button;
    osMessageQueuePut(resetQueueHandle, &value, 0, 0);

    osDelay(20);
  }
  /* USER CODE END StartTask04 */
}

/* USER CODE BEGIN Header_StartTask05 */
/**
* @brief Function implementing the UartTask thread.
*        Waits on sensorQueue for a new packet, then fully drains each
*        button queue (a button counts as pressed if it was down at ANY
*        sample since the last line), builds the text line the web page
*        expects (plus a trailing Mode field) and sends it over UART.
*        Lowest priority: its polled transmit must never starve the others.
* @param argument: Not used
* @retval None
*/
/* USER CODE END Header_StartTask05 */
void StartTask05(void *argument)
{
  /* USER CODE BEGIN StartTask05 */
  SensorPacket_t packet = {0};
  uint16_t button = 0, buttonleft = 0, buttonright = 0, buttonhead = 0, headmode = 0;
  uint16_t lastReset = 0, lastLeft = 0, lastRight = 0, lastHead = 0, any;
  for(;;)
  {
    /* Paced by SensorTask: one line per new sensor packet. */
    if (osMessageQueueGet(sensorQueueHandle, &packet, NULL, osWaitForever) == osOK)
    {
      /* Each button queue is drained completely. If the button was down at
       * ANY sample since the last line, report 1, so a quick tap is never
       * lost between two prints. No new sample -> keep previous value. */
      if (drain_queue(resetQueueHandle,  &any, &lastReset)) button      = any & 1;
      if (drain_queue(leftQueueHandle,   &any, &lastLeft))  buttonleft  = any & 1;
      if (drain_queue(rightQueueHandle,  &any, &lastRight)) buttonright = any & 1;
      if (drain_queue(headlightQueueHandle, &any, &lastHead)) {
        buttonhead = any & 1;
        headmode   = lastHead >> 1;      /* newest brightness mode */
      }

      char sAx[10], sAy[10], sAz[10], sGx[10], sGy[10], sGz[10], sTemp[10];
      format_float2(sAx, packet.Ax);
      format_float2(sAy, packet.Ay);
      format_float2(sAz, packet.Az);
      format_float2(sGx, packet.Gx);
      format_float2(sGy, packet.Gy);
      format_float2(sGz, packet.Gz);
      format_float2(sTemp, packet.Temp);

      char msg[160];
      int len = snprintf(msg, sizeof(msg),
              "Ax:%s Ay:%s Az:%s Gx:%s Gy:%s Gz:%s Temp:%sC Button:%d Left:%d Right:%d Head:%d Mode:%d\r\n",
              sAx, sAy, sAz, sGx, sGy, sGz, sTemp,
              button, buttonleft, buttonright, buttonhead, headmode);
      if (len > 0) {
        if (len > (int)sizeof(msg) - 1) len = sizeof(msg) - 1;
        HAL_UART_Transmit(&huart2, (uint8_t*)msg, (uint16_t)len, HAL_MAX_DELAY);
      }
    }
  }
  /* USER CODE END StartTask05 */
}

